import{_ as r,o as a,c as t,a2 as o}from"./chunks/framework.BXzK3EA4.js";const n="/assets/image%20(159).BhhrPqGb.png",i="/assets/image%20(160).Dsfip20e.png",s="/assets/image%20(161).DVtXjJ6M.png",m=JSON.parse('{"title":"Arrow","description":"","frontmatter":{},"headers":[],"relativePath":"connect-brokers/brokers/arrow.md","filePath":"connect-brokers/brokers/arrow.md"}'),p={name:"connect-brokers/brokers/arrow.md"};function d(l,e,c,g,h,u){return a(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="arrow" tabindex="-1">Arrow <a class="header-anchor" href="#arrow" aria-label="Permalink to &quot;Arrow&quot;">​</a></h1><h2 id="arrow-1" tabindex="-1">Arrow <a class="header-anchor" href="#arrow-1" aria-label="Permalink to &quot;Arrow&quot;">​</a></h2><p>Arrow (<a href="https://app.arrow.trade/" target="_blank" rel="noreferrer">arrow.trade</a>) is an ultra-low latency, speed-first retail brokerage and API platform built by <strong>iRage Broking</strong> (one of India&#39;s leading algorithmic and High-Frequency Trading firms). It provides ultra-fast APIs, zero intraday/F&amp;O brokerage, and institutional-grade tools to retail investors, regulated by NSE, BSE, and MCX. This API, used in the context of Tradeboard integration, enables automated trading strategies, real-time market data access, order management, and more.</p><p>The integration process involves creating an app in the Trading API section, capturing the generated credentials, and configuring them in Tradeboard&#39;s environmental variables.</p><h4 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h4><p>Before proceeding with authentication, please make sure you have:</p><p>1)Valid Arrow user credentials</p><p>2)Registered your redirect URL in the developer apps section (click on the profile icon and then click on <strong>Trading API&#39;s</strong> on the dropdown menu) of the main <a href="https://app.arrow.trade/" target="_blank" rel="noreferrer">Trading App</a></p><figure><img src="'+n+'" alt=""><figcaption></figcaption></figure><p>3)Filled in the form with the required data (static IP is now mandatory as per the latest SEBI Circular)</p><p>4)Your application credentials, <code>appID</code> and <code>appSecret</code>, handy (click on the <strong>+Create New</strong> button in the Trading API section)</p><h4 id="app-registration" tabindex="-1">App Registration <a class="header-anchor" href="#app-registration" aria-label="Permalink to &quot;App Registration&quot;">​</a></h4><p>Goto the main <a href="https://app.arrow.trade/" target="_blank" rel="noreferrer">Trading App</a> and login with your credentials. Sign up if you are a new user.</p><p>Step 1: Click on the profile icon and select <strong>Trading API&#39;s</strong> from the dropdown menu.</p><p>Step 2: Click the <strong>+Create New</strong> button to open the <strong>Create Trading API</strong> form.</p><p>Step 3: Fill in the form with the required details.</p><figure><img src="'+i+'" alt=""><figcaption></figcaption></figure><ul><li><strong>App name</strong>: a name to identify your app, for example <code>tradeboard</code></li><li><strong>App Icon</strong>: an optional icon for your app</li><li><strong>Redirect URL</strong>: <code>http://127.0.0.1:5000/arrow/callback</code></li><li><strong>Postback URL</strong>: a valid URL for order postback notifications (a dummy url such as <code>https://google.com</code> can be used)</li><li><strong>Description</strong>: a short description of your app, for example <code>tradeboard</code></li><li><strong>Static IP Address</strong>: your static IP, now mandatory as per the SEBI circular, for example <code>103.227.96.122</code></li></ul><p>Step 4: Click <strong>Create key</strong>.</p><p>Step 5: On the <strong>App Created Successfully!</strong> screen you will see your <strong>App ID</strong> and <strong>App Secret</strong>. Copy both and keep the App Secret secure.</p><figure><img src="'+s+`" alt=""><figcaption></figcaption></figure><p>Save the generated <code>appID</code> and <code>appSecret</code>. Later we will be adding them in the <a href="https://docs.algo.wesoftcorp.com/getting-started/windows-installation/environmental-variables" target="_blank" rel="noreferrer">environmental variable</a>.</p><p>Here is a sample of how the details would appear in a .env file for reference:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>BROKER_API_KEY = &#39;your_app_id_here&#39;</span></span>
<span class="line"><span>BROKER_API_SECRET = &#39;your_app_secret_here&#39;</span></span>
<span class="line"><span>REDIRECT_URL = &#39;http://127.0.0.1:5000/arrow/callback&#39;</span></span></code></pre></div><p>Integrating Tradeboard with Arrow&#39;s Trading API opens up possibilities for automated trading strategies, providing a powerful tool for traders and developers to act on market opportunities efficiently. It&#39;s essential to follow best practices for API integration, including handling rate limits, managing credentials securely, and ensuring robust error handling and logging mechanisms are in place.</p><h3 id="supported-exchanges" tabindex="-1">Supported Exchanges <a class="header-anchor" href="#supported-exchanges" aria-label="Permalink to &quot;Supported Exchanges&quot;">​</a></h3><p>Tradeboard reads this plugin&#39;s exchange list from <code>broker/arrow/plugin.json</code> and serves it to the app, so symbol search, the Strategy Builder and the tools pages only offer what the plugin actually handles.</p><ul><li><strong>Tradable:</strong> <code>NSE</code>, <code>BSE</code>, <code>NFO</code>, <code>BFO</code>, <code>CDS</code>, <code>BCD</code>, <code>MCX</code></li><li><strong>Index feeds:</strong> <code>NSE_INDEX</code>, <code>BSE_INDEX</code></li></ul>`,28)])])}const b=r(p,[["render",d]]);export{m as __pageData,b as default};
